def load_year_inputs(repo: Path, membership, year: int):
    ys=pd.Timestamp(f"{year}-01-01T00:00:00Z")
    ye=pd.Timestamp(f"{year+1}-01-01T00:00:00Z")
    pairs=year_pairs(membership,year)
    if not pairs:
        raise RunnerError(f"no C2 pairs {year}")
    raw_by_pair={}
    features={}
    four_hour={}
    for pair in pairs:
        path=repo/RAW_ROOT/pair/"1h.parquet"
        if not path.is_file():
            raise RunnerError(f"raw pair missing {pair}")
        raw=pd.read_parquet(
            path,engine="pyarrow",
            columns=["timestamp","open","high","low","close","volume"],
            filters=[("timestamp","<",ye.to_pydatetime())],
        )
        raw["timestamp"]=pd.to_datetime(raw["timestamp"],utc=True,errors="raise")
        if len(raw) and raw["timestamp"].max()>=ye:
            raise RunnerError(f"sealed cutoff violation {pair} {year}")
        raw_by_pair[pair]=raw
        features[pair]=prepare_features(raw,cutoff=ye)
        four_hour[pair]=build_four_hour_bars(raw,cutoff=ye)

    btc_path=repo/RAW_ROOT/"BTC-USDT"/"1h.parquet"
    btc=pd.read_parquet(
        btc_path,engine="pyarrow",
        columns=["timestamp","open","high","low","close","volume"],
        filters=[("timestamp","<",ye.to_pydatetime())],
    )
    btc["timestamp"]=pd.to_datetime(btc["timestamp"],utc=True,errors="raise")
    if len(btc) and btc["timestamp"].max()>=ye:
        raise RunnerError(f"BTC sealed cutoff violation {year}")
    state_frame=build_market_state_frame(btc,cutoff=ye)

    periods={f"YEAR_{year}":(ys,ye)}
    generated,_=scan_focus_signals(
        membership=membership,features=features,periods=periods,
        data_start=ys,data_cutoff=ye,guard_each_period_hours=None,
    )
    events=union_events(generated,universe_id="C2")
    if len(events):
        events["timestamp"]=pd.to_datetime(events["timestamp"],utc=True,errors="raise")
        entry=events["timestamp"]+pd.Timedelta(hours=1)
        events=events.loc[(entry>=ys)&((entry+pd.Timedelta(hours=168))<ye)].copy()
    return ys,ye,pairs,raw_by_pair,features,four_hour,state_frame,events.reset_index(drop=True)

def market_authority(*, raw_root: Path, pairs: list[str], rd26: Any, state: Any) -> tuple[dict[str, pd.DataFrame], pd.DataFrame, list[dict[str, Any]]]:
    frames: dict[str, pd.DataFrame] = {}; audit: list[dict[str, Any]] = []; cutoff = CUT.to_pydatetime()
    for index, pair in enumerate(pairs, start=1):
        path = raw_root / pair / "1h.parquet"
        if not path.is_file():
            raise ProofError(f"raw source missing: {path}")
        raw = pd.read_parquet(path, engine="pyarrow", filters=[("timestamp", "<", cutoff)])
        timestamps = pd.to_datetime(raw["timestamp"], utc=True, errors="raise")
        if raw.empty or bool((timestamps >= CUT).any()):
            raise ProofError(f"raw cutoff pushdown failed: {pair}")
        feature = rd26.prepare_features(raw, cutoff=CUT); frames[pair] = feature
        audit.append({"pair": pair, "row_count_materialized": len(feature), "first_timestamp": utc(feature["timestamp"].iloc[0]).isoformat(), "last_timestamp": utc(feature["timestamp"].iloc[-1]).isoformat(), "cutoff_exclusive": CUT.isoformat()})
        print(f"RAW_PRE2022={index}/{len(pairs)}:{pair}:{len(feature)}", flush=True)
    btc_raw = pd.read_parquet(raw_root / "BTC-USDT" / "1h.parquet", engine="pyarrow", filters=[("timestamp", "<", cutoff)])
    if bool((pd.to_datetime(btc_raw["timestamp"], utc=True, errors="raise") >= CUT).any()):
        raise ProofError("BTC state source crossed pre-2022 cutoff")
    state_frame = state.build_market_state_frame(btc_raw, cutoff=CUT)
    if bool((pd.to_datetime(state_frame["timestamp"], utc=True, errors="raise") >= CUT).any()):
        raise ProofError("state frame crossed pre-2022 cutoff")
    return frames, state_frame, audit

def load_hourly(
    repo: Path,
    trade_frames: Mapping[str, pd.DataFrame],
) -> dict[str, pd.DataFrame]:
    symbols = sorted(
        {
            str(symbol)
            for frame in trade_frames.values()
            for symbol in frame["symbol"].astype(str).unique()
        }
    )
    store = ParquetCandleStore(repo / "data/raw/rd16b")
    cutoff = SEALED_CUTOFF.to_pydatetime()
    result: dict[str, pd.DataFrame] = {}
    for index, symbol in enumerate(symbols, start=1):
        data_path = store.dataset_path(
            exchange_id="kucoin",
            symbol=symbol,
            timeframe="1h",
        )
        metadata_path = store.metadata_path(data_path)
        metadata = load_json(metadata_path)
        expected = metadata.get("sha256")
        if not isinstance(expected, str):
            raise BasePerformanceError(f"hourly metadata hash missing: {symbol}")
        if sha256(data_path) != expected:
            raise BasePerformanceError(f"hourly source hash mismatch: {symbol}")
        frame = pd.read_parquet(
            str(data_path),
            engine="pyarrow",
            filters=[("timestamp", "<", cutoff)],
        )
        normalized = normalize_hourly_bars(frame)
        result[symbol] = normalized
        print(
            f"P3E_BASE_BAR_LOAD={index}/{len(symbols)}:{symbol}:{len(normalized)}",
            flush=True,
        )
    return result

