def load_hourly(
    repo: Path,
    selected: dict[str, pd.DataFrame],
) -> dict[str, pd.DataFrame]:
    symbols = sorted(
        {
            str(symbol)
            for frame in selected.values()
            for symbol in frame["symbol"].astype(str).unique()
        }
    )
    store = ParquetCandleStore(repo / "data/raw/rd16b")
    frames: dict[str, pd.DataFrame] = {}
    cutoff = SEALED_CUTOFF.to_pydatetime()

    for index, symbol in enumerate(symbols, start=1):
        data_path = store.dataset_path(
            exchange_id="kucoin",
            symbol=symbol,
            timeframe="1h",
        )
        metadata_path = store.metadata_path(data_path)
        if not data_path.is_file():
            raise DryRunError(f"sealed 1h source missing: {data_path}")
        if not metadata_path.is_file():
            raise DryRunError(f"sealed 1h metadata missing: {metadata_path}")

        metadata = load_json(metadata_path)
        expected_hash = metadata.get("sha256")
        if not isinstance(expected_hash, str):
            raise DryRunError(f"sealed 1h metadata SHA missing: {symbol}")
        actual_hash = sha256(data_path)
        if actual_hash != expected_hash:
            raise DryRunError(f"sealed 1h source hash mismatch: {symbol}")
        if not all(
            (
                metadata.get("exchange_id") == "kucoin",
                metadata.get("symbol") == symbol,
                metadata.get("timeframe") == "1h",
            )
        ):
            raise DryRunError(f"sealed 1h metadata identity drift: {symbol}")

        frame = pd.read_parquet(
            str(data_path),
            engine="pyarrow",
            filters=[("timestamp", "<", cutoff)],
        )
        normalized = normalize_hourly_bars(frame)
        if normalized.empty:
            raise DryRunError(f"sealed 1h filtered source is empty: {symbol}")
        timestamps = pd.to_datetime(
            normalized["timestamp"],
            utc=True,
            errors="raise",
        )
        if bool((timestamps >= SEALED_CUTOFF).any()):
            raise DryRunError(f"post-2024 row entered memory: {symbol}")

        frames[symbol] = normalized
        print(
            "P3E_DRY_RUN_BAR_LOAD="
            f"{index}/{len(symbols)}:{symbol}:"
            f"{len(normalized)}:"
            f"{timestamps.iloc[0].isoformat()}:"
            f"{timestamps.iloc[-1].isoformat()}",
            flush=True,
        )
    return frames

def feature_integration_preflight(
    source_rows: list[dict[str, object]],
    variants: list[dict[str, object]],
    *,
    raw_root: Path,
) -> list[dict[str, object]]:
    representative: dict[str, dict[str, object]] = {}
    for variant in variants:
        family = str(variant["entry_family"])
        representative.setdefault(family, variant)
    if set(representative) != {
        "CONFIRMED_PULLBACK",
        "VOLATILITY_CONTRACTION_BREAKOUT",
    }:
        raise P2ARunnerError("both entry families were not resolved")

    rows: list[dict[str, object]] = []
    cutoff = SEALED_CUTOFF.to_pydatetime()
    for pair in _sample_pairs(source_rows):
        frame = pd.read_parquet(
            _parquet_path(raw_root, pair),
            engine="pyarrow",
            filters=[("timestamp", "<", cutoff)],
        )
        normalized = normalize_bars(frame.tail(2600))
        if len(normalized) < 2200:
            raise P2ARunnerError(f"insufficient sealed bars for feature preflight: {pair}")
        for family, variant in sorted(representative.items()):
            featured = feature_frame(normalized, variant)
            numeric = featured[
                [
                    "momentum_fast",
                    "momentum_slow",
                    "trend_persistence",
                    "atr",
                    "atr_percent",
                ]
            ].dropna()
            if numeric.empty:
                raise P2ARunnerError(f"feature preflight produced no valid rows: {pair}/{family}")
            maximum_timestamp = pd.Timestamp(featured["timestamp"].max())
            if maximum_timestamp >= SEALED_CUTOFF:
                raise P2ARunnerError(f"post-2024 row entered feature memory: {pair}")
            rows.append(
                {
                    "pair": pair,
                    "entry_family": family,
                    "variant_id": str(variant["variant_id"]),
                    "source_rows_loaded": len(normalized),
                    "valid_feature_rows": len(numeric),
                    "maximum_timestamp": maximum_timestamp.isoformat(),
                    "post_2024_accessed": False,
                }
            )
    return rows

